export interface Member {
  id: string;
  displayName: string;
  contact: string;
  registeredEpoch: number;
}

export interface MemberHandle {
  key: string;
}

export class MemberDirectory {
  private readonly members = new Map<string, Member>();

  public async add(member: Readonly<Member>): Promise<MemberHandle> {
    this.validate(member);
    if (this.members.has(member.id)) throw new Error('member already exists');
    this.members.set(member.id, member as Member);
    return { key: member.id };
  }

  public async get(id: string): Promise<Member> {
    const member = this.members.get(id);
    if (member === undefined) throw new Error('member not found');
    return { ...member };
  }

  private validate(member: Readonly<Member>): void {
    if (member.id.trim() === '') throw new Error('id is required');
    if (member.displayName.trim() === '') throw new Error('display name is required');
    if (member.contact.trim() === '') throw new Error('contact is required');
    if (!Number.isSafeInteger(member.registeredEpoch) || member.registeredEpoch < 0) {
      throw new Error('registered epoch is invalid');
    }
  }
}

