import { MemberDirectory, type Member } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

async function rejects(action: () => Promise<unknown>, message: string): Promise<void> {
  let rejected = false;
  try { await action(); } catch (error) { rejected = error instanceof Error; }
  assert(rejected, message);
}

async function run(): Promise<void> {
  const directory = new MemberDirectory();
  await rejects(() => directory.get('absent'), 'new directory is empty');

  const member: Member = { id: ' User-A ', displayName: ' Ada ', contact: ' ada@example.com ', registeredEpoch: 0 };
  const handle = await directory.add(member);
  equal(handle.key, ' User-A ', 'handle uses original exact ID');
  member.displayName = 'mutated caller';
  member.contact = 'mutated caller';
  const first = await directory.get(' User-A ');
  equal(first.id, ' User-A ', 'stored ID is not trimmed');
  equal(first.displayName, ' Ada ', 'stored display name is not rewritten or caller-mutated');
  equal(first.contact, ' ada@example.com ', 'stored contact is not rewritten or caller-mutated');
  equal(first.registeredEpoch, 0, 'zero epoch accepted');
  first.displayName = 'mutated retrieval';
  equal((await directory.get(' User-A ')).displayName, ' Ada ', 'retrieval is defensive');
  await rejects(() => directory.get('user-a'), 'matching is case-sensitive');
  await rejects(() => directory.get('User-A'), 'matching includes whitespace');
  await rejects(() => directory.add({ id: ' User-A ', displayName: 'Other', contact: 'x', registeredEpoch: 1 }), 'duplicate exact ID rejected');

  const maximum: Member = { id: 'max', displayName: 'Maximum', contact: 'm', registeredEpoch: Number.MAX_SAFE_INTEGER };
  await directory.add(maximum);
  equal((await directory.get('max')).registeredEpoch, Number.MAX_SAFE_INTEGER, 'maximum safe epoch accepted');

  const invalid: Member[] = [
    { id: '   ', displayName: 'Name', contact: 'c', registeredEpoch: 0 },
    { id: 'id1', displayName: '\t', contact: 'c', registeredEpoch: 0 },
    { id: 'id2', displayName: 'Name', contact: '\n ', registeredEpoch: 0 },
    { id: 'id3', displayName: 'Name', contact: 'c', registeredEpoch: -1 },
    { id: 'id4', displayName: 'Name', contact: 'c', registeredEpoch: 1.5 },
    { id: 'id5', displayName: 'Name', contact: 'c', registeredEpoch: Number.MAX_SAFE_INTEGER + 1 },
    { id: 'id6', displayName: 'Name', contact: 'c', registeredEpoch: NaN },
  ];
  for (const value of invalid) await rejects(() => directory.add(value), `invalid member ${value.id} rejected`);
  await rejects(() => directory.get('id3'), 'rejected member was not stored');
}

void run().catch((error) => { throw error; });

